'use strict';

const express = require('express');
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret';

// Role hierarchy: a user with role R satisfies requireRole(X) if rank(R) >= rank(X).
const ROLE_RANK = { viewer: 0, editor: 1, admin: 2 };

/**
 * Reusable RBAC middleware factory.
 * Usage: router.delete('/articles/:id', requireRole('admin'), handler)
 * Expects req.user.role to be populated by authenticate (JWT verification).
 */
function requireRole(minimumRole) {
  const minRank = ROLE_RANK[minimumRole];
  if (minRank === undefined) {
    throw new Error(`Unknown role: ${minimumRole}`);
  }
  return function (req, res, next) {
    const role = req.user && req.user.role;
    const rank = ROLE_RANK[role];
    if (rank === undefined || rank < minRank) {
      return res.status(403).json({ error: 'forbidden', required_role: minimumRole });
    }
    next();
  };
}

/** Verifies the Bearer JWT and populates req.user ({ sub, role }). */
function authenticate(req, res, next) {
  const header = req.headers.authorization || '';
  const [scheme, token] = header.split(' ');
  if (scheme !== 'Bearer' || !token) {
    return res.status(401).json({ error: 'unauthorized' });
  }
  try {
    req.user = jwt.verify(token, JWT_SECRET); // signed claim: { sub, role }
    next();
  } catch {
    return res.status(401).json({ error: 'unauthorized' });
  }
}

function createApp() {
  const app = express();
  app.use(express.json());

  // In-memory article store
  const articles = new Map([[1, { id: 1, title: 'Hello' }]]);
  let nextId = 2;

  const requireViewer = requireRole('viewer'); // any valid role passes
  const requireEditor = requireRole('editor');
  const requireAdmin = requireRole('admin');

  app.get('/articles/:id', authenticate, requireViewer, (req, res) => {
    const article = articles.get(Number(req.params.id));
    if (!article) return res.status(404).json({ error: 'not_found' });
    res.json(article);
  });

  app.post('/articles', authenticate, requireEditor, (req, res) => {
    const article = { id: nextId++, title: req.body.title ?? 'untitled' };
    articles.set(article.id, article);
    res.status(201).json(article);
  });

  app.put('/articles/:id', authenticate, requireEditor, (req, res) => {
    const id = Number(req.params.id);
    if (!articles.has(id)) return res.status(404).json({ error: 'not_found' });
    const updated = { ...articles.get(id), title: req.body.title ?? 'untitled' };
    articles.set(id, updated);
    res.json(updated);
  });

  app.delete('/articles/:id', authenticate, requireAdmin, (req, res) => {
    const id = Number(req.params.id);
    if (!articles.has(id)) return res.status(404).json({ error: 'not_found' });
    articles.delete(id);
    res.status(204).end();
  });

  return app;
}

module.exports = { createApp, requireRole, authenticate, signToken: (p) => jwt.sign(p, JWT_SECRET), JWT_SECRET };

if (require.main === module) {
  createApp().listen(process.env.PORT || 3000);
}

