'use strict';

const request = require('supertest');
const { createApp, signToken } = require('./app');

// Parameterized RBAC matrix: 3 roles x 4 methods = 12 cases.
// Each entry: [role, method, path, expectedStatus, expectedRequiredRoleOrNull]
const MATRIX = [
  ['viewer', 'GET',    '/articles/1',   200, null],
  ['viewer', 'POST',   '/articles',     403, 'editor'],
  ['viewer', 'PUT',    '/articles/1',   403, 'editor'],
  ['viewer', 'DELETE', '/articles/1',   403, 'admin'],

  ['editor', 'GET',    '/articles/1',   200, null],
  ['editor', 'POST',   '/articles',     201, null],
  ['editor', 'PUT',    '/articles/1',   200, null],
  ['editor', 'DELETE', '/articles/1',   403, 'admin'],

  ['admin',  'GET',    '/articles/1',   200, null],
  ['admin',  'POST',   '/articles',     201, null],
  ['admin',  'PUT',    '/articles/1',   200, null],
  ['admin',  'DELETE', '/articles/1',   204, null],
];

describe.each(MATRIX)('%s %s %s', (role, method, path, expectedStatus, requiredRole) => {
  let app;

  beforeAll(() => {
    app = createApp();
  });

  test(`token role=${role} -> ${expectedStatus}`, async () => {
    const token = signToken({ sub: `user-${role}`, role });
    const res = await request(app)
      [method.toLowerCase()](path)
      .set('Authorization', `Bearer ${token}`)
      .send(method === 'POST' || method === 'PUT' ? { title: 't' } : {});

    expect(res.status).toBe(expectedStatus);

    if (res.status === 403) {
      expect(res.body).toEqual({ error: 'forbidden', required_role: requiredRole });
    }
  });
});

